function renderSettings(){const s=source.settings;q('#settingsForm').timezone.value=s.timezone||'Asia/Tokyo';q('#settingsForm').weekStart.value=String(s.week_start??1);q('#settingsForm').reportRetentionDays.value=s.report_retention_days||90;q('#settingsForm').auditRetentionDays.value=s.audit_retention_days||365;q('#privacyReportRetention').textContent=(s.report_retention_days||90)+'日';q('#privacyAuditRetention').textContent=(s.audit_retention_days||365)+'日';const owner=source.admin?.role==='owner';q('#adminUserForm').hidden=!owner;q('#accessRows').innerHTML=(source.adminUsers||[]).map(u=>'<tr><td><b>'+esc(u.email)+'</b></td><td><select class="admin-role" data-admin-email="'+esc(u.email)+'" '+(!owner?'disabled':'')+'><option value="owner" '+(u.role==='owner'?'selected':'')+'>Owner</option><option value="manager" '+(u.role==='manager'?'selected':'')+'>Manager</option><option value="auditor" '+(u.role==='auditor'?'selected':'')+'>Auditor</option></select></td><td>'+(u.mfa_enabled?'<span class="badge ok">有効</span>':'<span class="badge warn">未設定</span>')+'</td><td>'+Number(u.session_count||0)+'件'+(owner&&u.email!==source.admin.email?' <button class="link revoke-sessions" data-admin-email="'+esc(u.email)+'">失効</button>':'')+'</td><td><select class="admin-status" data-admin-email="'+esc(u.email)+'" '+(!owner||u.email===source.admin.email?'disabled':'')+'><option value="active" '+(u.status==='active'?'selected':'')+'>有効</option><option value="suspended" '+(u.status==='suspended'?'selected':'')+'>停止</option></select></td></tr>').join('');qa('.admin-role,.admin-status').forEach(x=>x.onchange=()=>updateAdminUser(x.dataset.adminEmail));qa('.revoke-sessions').forEach(x=>x.onclick=()=>revokeAdminSessions(x.dataset.adminEmail))}
